interface.signature:
interface PrivacyService {
  EnableFingerprintingProtection() => (bool success);
  DisableFingerprintingProtection() => (bool success);
  EnableTrackerBlocking() => (bool success);
  DisableTrackerBlocking() => (bool success);
  GetPrivacyStatus() => (PrivacyStatus status);
  LogPrivacyChange(PrivacyChange change) => (bool success);
};

class PrivacyManager {
 public:
  virtual bool Initialize() = 0;
  virtual bool EnableFingerprintingProtection() = 0;
  virtual bool EnableTrackerBlocking() = 0;
  virtual PrivacyStatus GetStatus() const = 0;
  virtual bool LogPrivacyChange(const PrivacyChange& change) = 0;
};

export interface PrivacyManager {
  initialize(): Promise<Result>;
  enableFingerprintingProtection(): Promise<Result>;
  enableTrackerBlocking(): Promise<Result>;
  getStatus(): Promise<Result>;
  logPrivacyChange(change: PrivacyChange): Promise<Result>;
}
